import { useCallback } from 'react';
import { useAppDispatch } from '06_shared/hooks/useAppDispatch';
import { userApi } from '../api/userApi';
// Функція, що щоразу запитує НОВИЙ токен сокета. Токен живе 5 годин
// (WS_TOKEN_EXPIRE_MS на бекенді): закешований і використаний повторно, він
// після сну чи тривалого обриву відхилявся на кожній спробі реконекту.
export const useWebsocketTokenRequester = () => {
    const dispatch = useAppDispatch();
    return useCallback(async () => {
        const response = await dispatch(userApi.endpoints.getWebsocketToken.initiate(undefined, { forceRefetch: true, subscribe: false })).unwrap();
        return response.result ?? undefined;
    }, [dispatch]);
};
